(() => { const tabs=[...document.querySelectorAll('.deformed-tabs [role="tab"]')]; const panels=[document.getElementById('deformed-panel'),document.getElementById('dex-panel')]; const select=(tab)=>{tabs.forEach((t,i)=>{const active=t===tab;t.setAttribute('aria-selected',String(active));if(panels[i])panels[i].hidden=!active;});}; tabs.forEach(t=>t.addEventListener('click',()=>select(t))); document.querySelectorAll('.deformed-flip').forEach(button=>button.addEventListener('click',()=>{const flipped=button.classList.toggle('is-flipped');button.setAttribute('aria-pressed',String(flipped));const hint=button.querySelector('.deformed-face-hint');if(hint)hint.textContent=flipped?'クリックでデフォルメ画像':'クリックで元画像';})); })();